var Q16 = [
{n:1, q:'La Ley Orgánica de medidas de protección integral contra la violencia de género es la...', o:{a:'Ley Orgánica 4/2001.',b:'Ley Orgánica 1/2004.',c:'Ley Orgánica 3/2001.',d:'Ley Orgánica 1/2003.'}, correct:'b', why:{b:'La Ley Orgánica de medidas de protección integral contra la violencia de género es la LO 1/2004, de 28 de diciembre.'}},
{n:2, q:'Según la Organización Mundial de la Salud (OMS) la violencia de género comprende...', o:{a:'Violencia física.',b:'Violencia sexual.',c:'Violencia psicológica.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Según la OMS, la violencia de género comprende violencia física (a), sexual (b) y psicológica (c).'}},
{n:3, q:'Según la Organización Mundial de la Salud (OMS) la violencia de género...', o:{a:'Es un instrumento para mantener la discriminación de las mujeres.',b:'Es un instrumento para mantener la desigualdad de los hombres sobre las mujeres.',c:'Es un instrumento para mantener las relaciones de poder de los hombres sobre las mujeres.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Según la OMS, la violencia de género es un instrumento para mantener la discriminación (a), la desigualdad (b) y las relaciones de poder de los hombres sobre las mujeres (c).'}},
{n:4, q:'En la exposición de motivos de la Ley Orgánica 1/2004, la violencia de género es...', o:{a:'Una violencia que ancla sus raíces en el poder del hombre, que busca controlar y someter a la mujer.',b:'Un tipo de violencia caracterizado socialmente por su invisibilidad.',c:'Una violencia que se manifiesta en los tres ámbitos básicos de la relación de la persona: maltrato en el seno de las relaciones de pareja, agresión sexual en la vida social, y acoso en el medio laboral.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'d', why:{d:'La exposición de motivos de la LO 1/2004 presenta la violencia de género de forma más amplia que cualquiera de las opciones aisladas; la d indica que ninguna de las anteriores la describe completamente.'}},
{n:5, q:'Para la Fiscalía General del Estado, la violencia de género es...', o:{a:'Una violencia que ancla sus raíces en el poder del hombre, que busca controlar y someter a la mujer.',b:'Un tipo de violencia caracterizado socialmente por su invisibilidad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La FGE define la violencia de género como aquella que ancla sus raíces en el poder del hombre para controlar y someter a la mujer (a) y como un tipo de violencia caracterizada por su invisibilidad social (b).'}},
{n:6, q:'La violencia doméstica...', o:{a:'Es un concepto mucho más amplio que la violencia de género.',b:'Se utiliza para referirse a la violencia intrafamiliar ejercida en el terreno de la convivencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La violencia doméstica es un concepto más amplio que el de género (a) y se refiere a la violencia intrafamiliar en el terreno de la convivencia (b).'}},
{n:7, q:'La definición de violencia doméstica como "...los malos tratos o agresiones físicas, psicológicas, sexuales, o de otra índole, infringidas por personas del medio familiar y dirigida generalmente a los miembros más vulnerables..." ha sido realizada por...', o:{a:'La Organización Mundial de la Salud.',b:'La Fiscalía General del Estado.',c:'El Ministerio de Igualdad.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La definición de violencia doméstica citada corresponde a la Organización Mundial de la Salud (OMS).'}},
{n:8, q:'Existe una agravante de género en el...', o:{a:'Artículo 173.2 del Código Penal.',b:'Artículo 148.4 del Código Penal.',c:'Artículo 147.3 del Código Penal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art.148.4 CP recoge como circunstancia agravante de las lesiones que la víctima sea o haya sido la esposa o mujer ligada al autor por análoga relación de afectividad.'}},
{n:9, q:'Existe una agravante de género en el...', o:{a:'Artículo 22.4 del Código Penal.',b:'Artículo 22.3 del Código Penal.',c:'Artículo 22.5 del Código Penal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art.22.4 CP recoge como circunstancia agravante genérica cometer el delito por razones de género, entre otros motivos discriminatorios.'}},
{n:10, q:'En el artículo 148.4 del Código Penal, se agravan las penas previstas en el caso de lesiones...', o:{a:'Del artículo 147.1 del Código Penal.',b:'Del artículo 147.2 del Código Penal.',c:'Del artículo 149 del Código Penal.',d:'Del artículo 150 del Código Penal.'}, correct:'a', why:{a:'Art.148.4 CP: la agravante de género se aplica a las lesiones del art.147.1 CP (lesiones que requieren tratamiento médico o quirúrgico).'}},
{n:11, q:'En el artículo 148.4 del Código Penal, se castiga con pena de prisión de dos a cinco años, las lesiones del artículo 147.1 de este Código, cuando ...', o:{a:'La víctima hubiese sido esposa del autor.',b:'La víctima sea descendiente del autor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.148.4 CP: la agravante se aplica cuando la víctima sea o haya sido esposa del autor o mujer ligada a él por análoga relación de afectividad.'}},
{n:12, q:'En el artículo 148.4 del Código Penal, se castigan con pena de prisión de dos a cinco años, las lesiones del artículo 147.1 de este Código, cuando ...', o:{a:'La víctima sea mujer ligada al autor por análoga relación de afectividad al matrimonio.',b:'La víctima fuere una persona especialmente vulnerable.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.148.4 CP: se castiga con 2-5 años cuando la víctima es la pareja o expareja (a) o una persona especialmente vulnerable (b).'}},
{n:13, q:'En el artículo 148.4 del Código Penal, se castigan con pena de prisión de dos a cinco años, las lesiones del artículo 147.1 de este Código, cuando ...', o:{a:'La víctima sea, o haya sido, novia del autor, aunque no hayan convivido juntos.',b:'La víctima sea, o haya sido madre del autor, aunque no convivan juntos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.148.4 CP: la agravante se aplica cuando la víctima sea o haya sido pareja del autor (novia), aunque no hayan convivido juntos (a). No aplica si es la madre del autor (b).'}},
{n:14, q:'Para que pueda aplicarse la agravante de género del artículo 148.4 del Código Penal, es necesario que las lesiones causadas a la víctima ...', o:{a:'Supongan la pérdida o inutilidad de órgano o miembro no principal.',b:'Precisen para su sanidad, además de una primera asistencia facultativa, tratamiento médico o quirúrgico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.148.4 CP en relación con art.147.1 CP: para que se aplique la agravante del 148.4, las lesiones deben ser del art.147.1, es decir, que requieran tratamiento médico o quirúrgico además de primera asistencia.'}},
{n:15, q:'Leonardo golpea a su novia con una vara causándole una pequeña herida en el hombro que precisa de dos puntos de sutura. De acuerdo con lo previsto en el Código Penal, Leonardo podría ser condenado:', o:{a:'A una pena de prisión entre 3 meses y 3 años.',b:'A una pena de prisión entre 1 y 3 años.',c:'A una pena de prisión de 3 a 6 meses o multa de 6 a 12 meses.',d:'A una pena de prisión entre 2 y 5 años.'}, correct:'d', why:{d:'Los dos puntos de sutura implican que la lesión requiere tratamiento médico, por lo que se aplica el art.147.1 CP agravado por el art.148.4 CP (víctima es la novia), con pena de prisión de 2 a 5 años.'}},
{n:16, q:'En el artículo 153.1 del Código Penal se castiga al que, por cualquier medio o procedimiento, causare a otro menoscabo psíquico o una lesión de menor gravedad de las previstas en el artículo 147.2 de este Código, siempre que:', o:{a:'La ofendida sea o haya sido esposa o mujer que esté o haya estado ligada a él por análoga relación de afectividad aun sin convivencia.',b:'El ofendido sea ascendiente o descendiente del agresor.',c:'El ofendido sea hermano del agresor.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.153.1 CP: el tipo se aplica cuando la víctima es la esposa/pareja (a), ascendiente/descendiente (b) o hermano (c) del agresor.'}},
{n:17, q:'En el artículo 153.1 del Código Penal se castiga al que, por cualquier medio o procedimiento, maltratare de obra a otro sin causarle lesión, siempre que:', o:{a:'La ofendida sea o haya sido esposa o mujer que esté o haya estado ligada a él por análoga relación de afectividad aun sin convivencia.',b:'La ofendida sea una persona especialmente vulnerable que conviva con el autor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.153.1 CP: el maltrato sin lesión se castiga cuando la víctima es la pareja (a) o persona especialmente vulnerable que conviva con el autor (b).'}},
{n:18, q:'El delito de lesiones a la esposa o mujer ligada al autor por análoga relación de afectividad, tipificado en el artículo 153.1 del Código Penal, se castiga con:', o:{a:'Prisión de 6 meses a 2 años, o trabajos en beneficio de la comunidad de 31 a 80 días y, en todo caso, privación del derecho a la tenencia y porte de armas de 1 a 3 años.',b:'Prisión de 6 meses a 1 año, o trabajos en beneficio de la comunidad de 31 a 80 días y, en todo caso, privación del derecho a la tenencia y porte de armas de 1 año y un día a 3 años.',c:'Prisión de 6 meses a 2 años y trabajos en beneficio de la comunidad de 31 a 80 días y, en todo caso, privación del derecho a la tenencia y porte de armas de 1 a 3 años.',d:'Prisión de 6 meses a 1 año y trabajos en beneficio de la comunidad de 31 a 80 días y, en todo caso, privación del derecho a la tenencia y porte de armas de 1 año y un día a 3 años.'}, correct:'b', why:{b:'Art.153.1 CP: la pena es prisión de 6 meses a 1 año O TBC 31-80 días, y en todo caso privación del derecho a portar armas de 1 año y 1 día a 3 años.'}},
{n:19, q:'El delito de lesiones a la esposa, o mujer ligada al autor por análoga relación de afectividad, tipificado en el artículo 153.1 del Código Penal, podrá ser castigado con la pena de inhabilitación para el ejercicio de la patria potestad, tutela, curatela, guarda o acogimiento:', o:{a:'Cuando hubiere mediado ensañamiento.',b:'Cuando el juez o tribunal lo estime adecuado al interés del menor o persona con discapacidad necesitada de especial protección.',c:'Si el autor hubiese hecho uso de armas u otros objetos igualmente peligrosos para la vida o integridad física del ofendido.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.153.1 CP: la inhabilitación para el ejercicio de la patria potestad puede imponerse en todos esos supuestos.'}},
{n:20, q:'Comete delito del artículo 153.2 del Código Penal el que, por cualquier medio o procedimiento, causare a otro menoscabo psíquico o una lesión de menor gravedad de las previstas en el artículo 147.2 de éste Código, siempre que la víctima sea:', o:{a:'Esposa o persona ligada al autor por análoga relación de afectividad, aún sin convivencia.',b:'Ascendiente, descendiente o hermano del autor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.153.2 CP: el tipo se aplica cuando la víctima es ascendiente, descendiente o hermano del autor. La pareja corresponde al art.153.1.'}},
{n:21, q:'Cuando los delitos de maltrato o lesiones previstos en los apartados 1 y 2 del artículo 153 del Código Penal se perpetren en presencia de menores, la pena a imponer será:', o:{a:'La respectivamente prevista para cada supuesto, en su mitad superior.',b:'La pena superior en grado a la respectivamente prevista en cada caso.',c:'La pena superior en uno o dos grados a la respectivamente prevista para cada caso.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.153.3 CP: la pena se impone en su mitad superior cuando los hechos se cometen en presencia de menores.'}},
{n:22, q:'Cuando en los delitos de maltrato o lesiones previstos en los apartados 1 y 2 del artículo 153 del Código Penal se utilicen armas la pena a imponer será:', o:{a:'La respectivamente prevista para cada supuesto, en su mitad superior.',b:'La pena superior en grado a la respectivamente prevista en cada caso.',c:'La pena superior en uno o dos grados a la respectivamente prevista para cada caso.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.153.3 CP: el uso de armas en los delitos del art.153 también da lugar a imponer la pena en su mitad superior.'}},
{n:23, q:'Cuando los delitos de maltrato o lesiones previstos en los apartados 1 y 2 del artículo 153 del Código Penal tengan lugar en el domicilio común o en el de la víctima, la pena a imponer será:', o:{a:'La respectivamente prevista para cada supuesto, en su mitad superior.',b:'La pena superior en grado a la respectivamente prevista en cada caso.',c:'La pena superior en uno o dos grados a la respectivamente prevista para cada caso.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.153.3 CP: cometer los hechos en el domicilio común o de la víctima agrava la pena a su mitad superior.'}},
{n:24, q:'Cuando los delitos de maltrato o lesiones previstos en los apartados 1 y 2 del artículo 153 del Código Penal se realicen quebrantando una pena de las previstas en el artículo 48 de éste Código, o una medida cautelar o de seguridad de la misma naturaleza, la pena a imponer será:', o:{a:'La respectivamente prevista para cada supuesto, en su mitad superior.',b:'La pena superior en grado a la respectivamente prevista en cada caso.',c:'La pena superior en uno o dos grados a la respectivamente prevista para cada caso.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.153.3 CP: quebrantar las medidas del art.48 en el contexto del art.153 agrava la pena a su mitad superior.'}},
{n:25, q:'Respecto a los delitos de maltrato o lesiones previstos en los apartados 1 y 2 del artículo 153 del Código Penal, indique la respuesta correcta:', o:{a:'Pueden ser castigados con las respectivas penas en su mitad inferior, siempre que el Juez o Tribunal lo razone en la sentencia, en atención a las circunstancias personales del autor y las concurrentes en la realización del hecho.',b:'Pueden ser castigados con la pena inferior en grado, siempre que el Juez o Tribunal lo razone en la sentencia, en atención a las circunstancias personales del autor y las concurrentes en la realización del hecho.',c:'Pueden ser castigados con las respectivas penas en su mitad inferior, siempre que el Juez o Tribunal lo razone en la sentencia, en atención a los medios utilizados y al resultado producido.',d:'Pueden ser castigados con la pena inferior en grado, siempre que el Juez o Tribunal lo razone en la sentencia, en atención a los medios utilizados y al resultado producido.'}, correct:'b', why:{b:'Art.153.4 CP: el juez puede imponer la pena inferior en grado cuando lo razone atendiendo a las circunstancias personales del autor y las del hecho.'}},
{n:26, q:'En el artículo 173.2 del Código Penal se castiga a quienes ejerzan violencia física o psíquica sobre quien sea o haya sido su cónyuge, o sobre la persona a la que esté o haya estado ligada con el autor por análoga relación de afectividad, aun sin convivencia, siempre y cuando:', o:{a:'La violencia se ejerza habitualmente.',b:'Los actos de violencia tengan un carácter particularmente degradante o vejatorio.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.173.2 CP: el requisito esencial es que la violencia sea habitual. No basta con que sea degradante.'}},
{n:27, q:'En el artículo 173.2 del Código Penal se castiga a quienes ejerzan violencia física o psíquica, de manera habitual sobre ...', o:{a:'Ascendientes.',b:'Descendientes.',c:'Hermanos por naturaleza.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.173.2 CP: el maltrato habitual se castiga cuando la víctima es ascendiente (a), descendiente (b) o hermano (c), entre otros.'}},
{n:28, q:'En el artículo 173.2 del Código Penal se castiga a quienes ejerzan violencia física o psíquica, de manera habitual sobre ...', o:{a:'Hijos del cónyuge o conviviente.',b:'Hermanos por afinidad.',c:'Personas con discapacidad necesitadas de especial protección, que convivan con los autores.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.173.2 CP: también son víctimas los hijos del cónyuge (a), hermanos por afinidad (b) y personas con discapacidad que convivan (c).'}},
{n:29, q:'En el artículo 173.2 del Código Penal se castiga a quienes ejerzan violencia física o psíquica, de manera habitual sobre...', o:{a:'Personas que se hallen sujetas a la tutela del cónyuge o conviviente.',b:'Personas que se hallen sujetas a la curatela del cónyuge o conviviente.',c:'Personas que se hallen sujetas a la guarda de hecho del cónyuge o conviviente.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.173.2 CP: también son víctimas las personas bajo tutela (a), curatela (b) o guarda de hecho (c) del agresor o su cónyuge.'}},
{n:30, q:'Para que pueda aplicarse el artículo 173.2 del Código Penal a quienes ejerzan violencia física o psíquica, de manera habitual, sobre persona no comprendida en ninguna relación familiar, se requiere...', o:{a:'Que no exista relación de servicio.',b:'Que la persona se encuentre integrada en el núcleo de convivencia familiar del autor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.173.2 CP: para personas no familiares, se requiere que no haya relación de servicio (a) y que estén integradas en el núcleo de convivencia familiar (b).'}},
{n:31, q:'El delito de maltrato habitual del artículo 173.2 del Código Penal es aplicable a...', o:{a:'Los compañeros de estudios de la víctima.',b:'Las personas que por su especial vulnerabilidad se encuentran sometidas a custodia o guarda en centros públicos o privados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.173.2 CP: también son víctimas del maltrato habitual las personas especialmente vulnerables bajo custodia o guarda en centros (b). Los compañeros de estudios no están incluidos (a).'}},
{n:32, q:'El delito de maltrato habitual del artículo 173.2 del Código Penal se castiga con la pena de...', o:{a:'Prisión de seis meses a tres años.',b:'Privación del derecho a la tenencia y porte de armas de tres a cinco años',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.173.2 CP: el maltrato habitual se castiga con prisión de 6 meses a 3 años (a) y privación del derecho a portar armas de 3 a 5 años (b).'}},
{n:33, q:'En el delito de violencias habituales en el ámbito familiar del artículo 173.2 del Código Penal, se impondrán las penas señaladas en su mitad superior cuando:', o:{a:'Los actos de violencia se perpetren en presencia de menores.',b:'Los actos de violencia se perpetren en presencia de incapaces.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.173.3 CP: la pena se impone en su mitad superior cuando los actos se cometen en presencia de menores (a) o incapaces (b).'}},
{n:34, q:'En el delito de violencias habituales en el ámbito familiar del artículo 173.2 del Código Penal, se impondrán las penas señaladas en su mitad superior cuando:', o:{a:'Los actos de violencia se perpetren utilizando cualquier objeto peligroso.',b:'Los actos de violencia se perpetren utilizando armas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.173.3 CP: usar cualquier objeto peligroso (a) o armas (b) también dan lugar a la pena en su mitad superior.'}},
{n:35, q:'En el delito de violencias habituales en el ámbito familiar del artículo 173.2 del Código Penal, se impondrán las penas señaladas en su mitad superior cuando:', o:{a:'Los actos se realicen quebrantando una pena de las contempladas en el artículo 48 del Código Penal o una medida cautelar o prohibición de la misma naturaleza.',b:'Los actos de violencia tengan lugar en el domicilio común o en el domicilio de la víctima.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.173.3 CP: quebrantar medidas del art.48 (a) y cometer los hechos en el domicilio (b) agravan a mitad superior.'}},
{n:36, q:'Para apreciar la habitualidad en el delito de violencias familiares del artículo 173.2 del Código Penal:', o:{a:'Se atenderá al número de actos de violencia que resulten acreditados.',b:'Se atenderá a la proximidad temporal de los actos de violencia realizados, con independencia de que dicha violencia se haya ejercido sobre la misma o sobre diferentes víctimas.',c:'Se atenderá a la proximidad temporal de los actos de violencia realizados, con independencia de que dicha violencia haya sido objeto de enjuiciamiento en procesos anteriores.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.173.3 CP: para apreciar la habitualidad se atiende al número de actos (a), la proximidad temporal aunque sean víctimas distintas (b) y aunque hayan sido objeto de enjuiciamiento previo (c).'}},
{n:37, q:'En el delito de maltrato habitual del artículo 173.2 del Código Penal, además de las penas establecidas, podrá imponerse...', o:{a:'La inhabilitación para sufragio activo y pasivo, profesión u oficio.',b:'Una medida de libertad vigilada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.173.2 CP: además de las penas principales, podrá imponerse la medida de libertad vigilada. La inhabilitación para sufragio no está prevista expresamente.'}},
{n:38, q:'En lo que respecta al delito de maltrato habitual del artículo 173.2 del Código Penal, el Tribunal Supremo, en la STS 684/2021, ha dicho...', o:{a:'Que la declaración de la víctima es prueba bastante, a analizar por el Juez o Tribunal.',b:'Que la aplicación de este tipo penal es compatible con la sanción separada de los distintos hechos violentos ejercidos sobre la víctima.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'STS 684/2021: la declaración de la víctima es prueba bastante (a) y el tipo del maltrato habitual es compatible con sancionar por separado los hechos violentos concretos (b).'}},
{n:39, q:'En lo que respecta al delito de maltrato habitual del artículo 173.2 del Código Penal, el Tribunal Supremo, en la STS 684/2021, ha dicho...', o:{a:'Que el delito se consuma cuando se crea una convivencia insoportable para la víctima, la cual vive y respira en una situación de miedo, depresión y ansiedad, temiendo incluso por su vida.',b:'Que para poder condenar por este delito se requiere un esfuerzo de la víctima en la concreción de las fechas y momentos en que sufrió los episodios de violencia denunciados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'STS 684/2021: el delito se consuma cuando se crea una convivencia insoportable de miedo y ansiedad para la víctima (a). No se exige que la víctima concrete fechas exactas (b es incorrecta).'}},
{n:40, q:'En lo que respecta al delito de maltrato habitual del artículo 173.2 del Código Penal, el Tribunal Supremo, en la STS 684/2021, ha dicho...', o:{a:'Que la habitualidad no es un problema aritmético de un número mínimo de comportamientos individualizados que se sumen hasta alcanzar una determinada cifra.',b:'Que será conducta habitual la del que actúa repetidamente en la misma dirección, con o sin condenas previas, que de existir, hay prueba de aquella, aunque no la única vía para su acreditación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'STS 684/2021: la habitualidad no es aritmética (a) y se acredita por la conducta repetida en la misma dirección, con o sin condenas previas (b).'}},
{n:41, q:'En lo que respecta al delito de maltrato habitual del artículo 173.2 del Código Penal, el Tribunal Supremo, en la STS 684/2021, ha dicho...', o:{a:'Que el maltrato habitual genera tantos delitos del artículo 173.2 como episodios de maltrato se hayan producido.',b:'Que con el maltrato habitual se ejerce un ambiente infernal e irrespirable que envolverá la convivencia, que puede ser sobre el mismo, o sobre diferentes sujetos pasivos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'STS 684/2021: el maltrato habitual crea un ambiente infernal en la convivencia, pudiendo afectar a distintos sujetos pasivos (b). El maltrato habitual es un único delito, no tantos como episodios (a es incorrecta).'}},
{n:42, q:'En lo que respecta al delito de maltrato habitual del artículo 173.2 del Código Penal, el Tribunal Supremo, en la STS 684/2021, ha dicho...', o:{a:'Que el retraso en denunciar la víctima los actos de maltrato habitual no puede ser tenido en cuenta para minimizar la credibilidad de ésta.',b:'Que en el maltrato habitual, la inexistencia de denuncias previas no es entendible como una declaración no cierta o inexacta, o que la víctima falta a la verdad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'STS 684/2021: el retraso en denunciar no resta credibilidad (a) y la falta de denuncias previas no indica falsedad de la declaración (b).'}},
{n:43, q:'Las amenazas leves constitutivas de violencia de género se castigan en el...', o:{a:'Artículo 171.1 del Código Penal.',b:'Artículo 171.2 del Código Penal.',c:'Artículo 171.3 del Código Penal.',d:'Artículo 171.4 del Código Penal.'}, correct:'d', why:{d:'Art.171.4 CP: las amenazas leves constitutivas de violencia de género se castigan en el artículo 171.4 del CP.'}},
{n:44, q:'Las amenazas leves constitutivas de violencia doméstica se castigan en el...', o:{a:'Artículo 171.3 del Código Penal.',b:'Artículo 171.4 del Código Penal.',c:'Artículo 171.5 del Código Penal.',d:'Artículo 171.6 del Código Penal.'}, correct:'c', why:{c:'Art.171.5 CP: las amenazas leves constitutivas de violencia doméstica (contra personas del art.173.2 distintas de la pareja) se castigan en el art.171.5 CP.'}},
{n:45, q:'El que de modo leve amenace a quien sea o haya sido su esposa, será castigado con...', o:{a:'Prisión de 3 a 6 meses, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',b:'Prisión de 6 meses a un año, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',c:'Prisión de 3 meses a un año, o trabajos en beneficio de la comunidad de 31 a 90 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',d:'Prisión de 6 meses a un año, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a seis años.'}, correct:'b', why:{b:'Art.171.4 CP: amenazar levemente a la esposa o expareja se castiga con prisión de 6 meses a 1 año O TBC 31-80 días, y privación del derecho a portar armas de 1 año y 1 día a 3 años.'}},
{n:46, q:'El que de modo leve amenace a cualquier persona vulnerable con la que conviva, será castigado con...', o:{a:'Prisión de 3 meses a un año, o trabajos en beneficio de la comunidad de 31 a 90 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',b:'Prisión de 6 meses a un año, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a seis años.',c:'Prisión de 3 a 6 meses, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',d:'Prisión de 3 meses a un año, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.'}, correct:'d', why:{d:'Art.171.5 CP: amenazar levemente a persona vulnerable conviviente se castiga con prisión de 3 meses a 1 año O TBC 31-80 días, y privación del derecho a portar armas de 1a1d a 3 años.'}},
{n:47, q:'El delito de amenazas leves del artículo 171.4 del Código Penal es aplicable...', o:{a:'Cuando la víctima, hombre o mujer, haya estado ligada al autor por una análoga relación de afectividad a la del matrimonio.',b:'Cuando la víctima, que en todo caso tiene que ser mujer, sea una persona especialmente vulnerable que conviva con el autor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.171.4 CP: el tipo de amenazas leves de violencia de género es aplicable cuando la víctima (hombre o mujer) haya estado ligada al autor por análoga relación de afectividad.'}},
{n:48, q:'El delito de amenazas leves del artículo 171.5 del Código Penal requiere...', o:{a:'Que las amenazas se lleven a cabo con armas o instrumentos peligrosos.',b:'Que el sujeto pasivo de estas amenazas sea alguna de las personas a las que se refiere el artículo 173.2 CP.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.171.5 CP: el delito requiere que el sujeto pasivo sea alguna de las personas del art.173.2 CP (ámbito doméstico). No requiere necesariamente armas.'}},
{n:49, q:'El delito de amenazas leves del artículo 171.5 del Código Penal requiere...', o:{a:'Que la víctima sea alguna de las personas a las que se refiere el artículo 173.2 CP, exceptuadas las comprendidas en el artículo 171.4 de este Código.',b:'Que la víctima sea una persona especialmente vulnerable que conviva con el autor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.171.5 CP: el tipo se aplica cuando la víctima es del ámbito del art.173.2 CP, exceptuando a las que ya quedan cubiertas por el art.171.4 (pareja/expareja).'}},
{n:50, q:'El que de modo leve amenace con armas u otros instrumentos peligrosos, a alguna de las personas a las que se refiere el artículo 173.2 CP, exceptuadas las indicadas en el apartado 4 del artículo 171.4 CP, será castigado con...', o:{a:'Prisión de 3 a 6 meses, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',b:'Prisión de 6 meses a un año, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',c:'Prisión de 3 meses a un año, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',d:'Prisión de 3 meses a un año, o trabajos en beneficio de la comunidad de 31 a 90 días, y privación del derecho a la tenencia y porte de armas de uno a seis años.'}, correct:'a', why:{a:'Art.171.5 CP: amenazar levemente con armas a personas del ámbito doméstico (no pareja) se castiga con prisión de 3 a 6 meses O TBC 31-80 días, y privación de armas de 1a1d a 3 años.'}},
{n:51, q:'Las penas previstas por los delitos de amenazas leves de los artículos 171.4 y 171.5 del Código Penal, se impondrán en su mitad superior cuando...', o:{a:'Se lleven a cabo con armas o instrumentos peligrosos.',b:'Se lleven a cabo en presencia de menores.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.171.6 CP: las penas de amenazas leves se imponen en su mitad superior cuando se llevan a cabo con armas (a) o en presencia de menores (b).'}},
{n:52, q:'Las penas previstas por los delitos de amenazas leves de los artículos 171.4 y 171.5 del Código Penal, se impondrán en su mitad superior cuando...', o:{a:'Tengan lugar en el domicilio común o de la víctima.',b:'Se hayan realizado aprovechándose de determinadas circunstancias de tiempo y lugar, o mediante el uso de publicidad.',c:'Medie denuncia de la persona agraviada.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'Art.171.6 CP: la pena se impone en su mitad superior cuando los hechos tienen lugar en el domicilio común o de la víctima (a).'}},
{n:53, q:'Las penas previstas por los delitos de amenazas leves de los artículos 171.4 y 171.5 del Código Penal, se impondrán en su mitad superior cuando...', o:{a:'Los hechos se realicen quebrantando una pena de las previstas en el artículo 48 del Código Penal, o una medida cautelar o de seguridad de la misma naturaleza.',b:'Se aumente deliberada e inhumanamente el sufrimiento de la víctima, causando a ésta padecimientos innecesarios para la ejecución del delito, o hubiere mediado ensañamiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.171.6 CP: quebrantar medidas del art.48 CP hace que la pena se imponga en su mitad superior (a). El ensañamiento (b) no está previsto como agravante específico de este artículo.'}},
{n:54, q:'El delito de amenazas leves del artículo 171.7 del Código Penal...', o:{a:'Solo es aplicable cuando no concurre ninguno de los supuestos previstos en los apartados 1 a 6 del artículo 171.',b:'Solo es perseguible mediante denuncia de la persona agraviada, salvo que la víctima sea persona de las comprendidas en el artículo 173.2 del CP.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.171.7 CP: el tipo residual de amenazas leves solo aplica cuando no hay otra modalidad (a) y es perseguible mediante denuncia salvo que la víctima sea del art.173.2 (b).'}},
{n:55, q:'El delito de amenazas leves del artículo 171.7 del Código Penal, cometido sobre alguna de las personas a las que hace referencia el artículo 173.2 del CP, se castiga con las penas de...', o:{a:'Prisión de 3 a 6 meses, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',b:'Trabajos en beneficio de la comunidad de 31 a 90 días, y privación del derecho a la tenencia y porte de armas de uno a tres años.',c:'Localización permanente de cinco a treinta días, siempre en domicilio diferente y alejado del de la víctima, o trabajos en beneficio de la comunidad de 31 a 80 días, o multa de uno a tres meses.',d:'Localización permanente de cinco a treinta días, siempre en domicilio diferente y alejado del de la víctima, o trabajos en beneficio de la comunidad de cinco a treinta días, o multa de uno a cuatro meses.'}, correct:'c', why:{c:'Art.171.7 CP: el delito de amenazas leves residuales sobre personas del art.173.2 se castiga con localización permanente 5-30 días, TBC 31-80 días o multa 1-3 meses.'}},
{n:56, q:'Las coacciones leves constitutivas de violencia de género se castigan en el...', o:{a:'Artículo 172.1 del Código Penal.',b:'Artículo 172.2 del Código Penal.',c:'Artículo 172.3 del Código Penal.',d:'Artículo 172.4 del Código Penal.'}, correct:'b', why:{b:'Art.172.2 CP: las coacciones leves constitutivas de violencia de género se castigan en el artículo 172.2 del CP.'}},
{n:57, q:'Las coacciones leves constitutivas de violencia doméstica se castigan en el...', o:{a:'Artículo 172.1 del Código Penal.',b:'Artículo 172.2 del Código Penal.',c:'Artículo 172.3 del Código Penal.',d:'Artículo 172.4 del Código Penal.'}, correct:'c', why:{c:'Art.172.3 CP: las coacciones leves constitutivas de violencia doméstica (contra personas del art.173.2 distintas de la pareja) se castigan en el art.172.3 CP.'}},
{n:58, q:'El que de modo leve coaccione a quien sea o haya sido su esposa, o mujer que esté o haya estado ligada a él por análoga relación de afectividad, aun sin convivencia, será castigado con...', o:{a:'Prisión de 3 a 6 meses, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',b:'Prisión de 6 meses a un año, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',c:'Prisión de 3 meses a un año, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',d:'Prisión de 3 meses a un año, o trabajos en beneficio de la comunidad de 31 a 90 días, y privación del derecho a la tenencia y porte de armas de uno a seis años.'}, correct:'b', why:{b:'Art.172.2 CP: coaccionar levemente a la esposa o expareja se castiga con prisión de 6 meses a 1 año O TBC 31-80 días, y privación del derecho a portar armas de 1a1d a 3 años.'}},
{n:59, q:'El que de modo leve coaccione a una persona especialmente vulnerable con la que conviva, será castigado con...', o:{a:'Prisión de 3 meses a un año, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',b:'Prisión de 3 meses a un año, o trabajos en beneficio de la comunidad de 31 a 90 días, y privación del derecho a la tenencia y porte de armas de un año y un día a seis años.',c:'Prisión de 3 a 6 meses, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',d:'Prisión de 6 meses a un año, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.'}, correct:'a', why:{a:'Art.172.3 CP: coaccionar levemente a persona vulnerable conviviente se castiga con prisión de 3 meses a 1 año O TBC 31-80 días, y privación del derecho a portar armas de 1a1d a 3 años.'}},
{n:60, q:'Las penas previstas por los delitos de coacciones leves del artículo 172.2 del Código Penal, se impondrán en su mitad superior cuando...', o:{a:'Se lleven a cabo con armas o instrumentos peligrosos.',b:'Se lleven a cabo en presencia de menores.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.172.2 CP: las penas se imponen en su mitad superior cuando se usan armas (a) o se cometen en presencia de menores (b).'}},
{n:61, q:'Las penas previstas por los delitos de coacciones leves del artículo 172.2 del Código Penal, se impondrán en su mitad superior cuando...', o:{a:'Tengan lugar en el domicilio común o de la víctima.',b:'Se hayan realizado aprovechándose de determinadas circunstancias de tiempo y lugar, o mediante el uso de publicidad.',c:'Medie denuncia de la persona agraviada.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'Art.172.2 CP: la pena se impone en su mitad superior cuando los hechos tienen lugar en el domicilio común o de la víctima.'}},
{n:62, q:'Las penas previstas por los delitos de coacciones leves del artículo 172.2 del Código Penal, se impondrán en su mitad superior cuando...', o:{a:'Los hechos se realicen quebrantando una pena de las previstas en el artículo 48 del Código Penal, o una medida cautelar o de seguridad de la misma naturaleza.',b:'Se aumente deliberada e inhumanamente el sufrimiento de la víctima, causando a ésta padecimientos innecesarios para la ejecución del delito, o hubiere mediado ensañamiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.172.2 CP: quebrantar medidas del art.48 CP (a) agrava la pena a su mitad superior. El ensañamiento (b) no es agravante específico de este artículo.'}},
{n:63, q:'El delito de coacciones leves del artículo 172.3 del Código Penal...', o:{a:'Solo es aplicable cuando no concurre ninguno de los supuestos previstos en los apartados 1 y 2 del artículo 172.',b:'Solo es perseguible mediante denuncia de la persona agraviada, salvo que la víctima sea persona de las comprendidas en el artículo 173.2 CP.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.172.3 CP: es subsidiario de los tipos del art.172.1 y 172.2 (a) y es perseguible mediante denuncia salvo cuando la víctima es del art.173.2 (b).'}},
{n:64, q:'El delito de coacciones leves del artículo 172.3 del Código Penal, cometido sobre alguna de las personas a las que hace referencia el artículo 173.2 del CP, se castiga con las penas de...', o:{a:'Localización permanente de cinco a treinta días, siempre en domicilio diferente y alejado del de la víctima, o trabajos en beneficio de la comunidad de 31 a 80 días, o multa de uno a tres meses.',b:'Localización permanente de cinco a treinta días, siempre en domicilio diferente y alejado del de la víctima, o trabajos en beneficio de la comunidad de cinco a treinta días, o multa de uno a cuatro meses.',c:'Prisión de 3 a 6 meses, o trabajos en beneficio de la comunidad de 31 a 80 días, y privación del derecho a la tenencia y porte de armas de un año y un día a tres años.',d:'Trabajos en beneficio de la comunidad de 31 a 90 días, y privación del derecho a la tenencia y porte de armas de uno a tres años.'}, correct:'a', why:{a:'Art.172.3 CP: las coacciones leves sobre personas del art.173.2 se castigan con localización permanente 5-30 días, TBC 31-80 días o multa 1-3 meses.'}},
{n:65, q:'El quebrantamiento de alguna de las penas, medidas cautelares o de seguridad, contempladas en el artículo 48 del Código Penal, en las que el ofendido sea alguna de las personas a las que se refiere el artículo 173.2 de este Código, se castiga en...', o:{a:'El artículo 368.1 del Código Penal.',b:'El artículo 368.2 del Código Penal.',c:'El artículo 468.1 del Código Penal.',d:'El artículo 468.2 del Código Penal.'}, correct:'d', why:{d:'Art.468.2 CP: el quebrantamiento de medidas del art.48 CP cuando el ofendido es del ámbito del art.173.2 se castiga en el art.468.2 CP.'}},
{n:66, q:'El quebrantamiento de alguna de las penas, medidas cautelares o de seguridad, contempladas en el artículo 48 del Código Penal, en las que el ofendido sea alguna de las personas a las que se refiere el artículo 173.2 de este Código, se castiga con...', o:{a:'Trabajos en beneficio de la comunidad de 31 a 90 días, y privación del derecho a la tenencia y porte de armas de uno a tres años.',b:'Multa de 12 a 24 meses.',c:'Prisión de 6 meses a un año.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.468.2 CP: el quebrantamiento de medidas de protección en violencia doméstica/género se castiga con prisión de 6 meses a 1 año.'}},
{n:67, q:'Los que quebrantaren una medida de libertad vigilada serán castigados con...', o:{a:'Prisión de 6 meses a un año.',b:'Trabajos en beneficio de la comunidad de 31 a 90 días, y privación del derecho a la tenencia y porte de armas de uno a tres años.',c:'Multa de 12 a 24 meses.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.468.3 CP: el quebrantamiento de la medida de libertad vigilada se castiga con TBC de 31 a 90 días y privación del derecho a portar armas de 1 a 3 años.'}},
{n:68, q:'En el artículo 468.3 del Código Penal se castiga a...', o:{a:'Los que inutilicen o perturben el funcionamiento normal de los dispositivos técnicos que hubieran sido dispuestos para controlar el cumplimiento de las penas, medidas de seguridad o medidas cautelares.',b:'Los que no lleven consigo u omitan las medidas exigibles para mantener el correcto estado de funcionamiento de los dispositivos técnicos que hubieran sido dispuestos para controlar el cumplimiento de las penas, medidas de seguridad o medidas cautelares.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.468.3 CP: tanto inutilizar/perturbar los dispositivos de control (a) como omitir las medidas para mantenerlos en correcto funcionamiento (b) están tipificados.'}},
{n:69, q:'En el artículo 468.3 del Código Penal se determina que, los que inutilicen o perturben el funcionamiento normal de los dispositivos técnicos que hubieran sido dispuestos para controlar el cumplimiento de las penas, medidas de seguridad o medidas cautelares, serán castigados con la pena de...', o:{a:'Multa de 6 a 12 meses.',b:'Multa de 12 a 24 meses.',c:'Multa de 1 a 3 meses.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.468.3 CP: la inutilización de dispositivos de control se castiga con multa de 12 a 24 meses.'}},
{n:70, q:'En el artículo 468.3 del Código Penal se determina que, los que no lleven consigo u omitan las medidas exigibles para mantener el correcto estado de funcionamiento de los dispositivos técnicos que hubieran sido dispuestos para controlar el cumplimiento de las penas, medidas de seguridad o medidas cautelares, serán castigados con la pena de...', o:{a:'Multa de 6 a 12 meses.',b:'Multa de 12 a 24 meses.',c:'Multa de 1 a 3 meses.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.468.3 CP: la omisión de medidas para mantener los dispositivos de control en correcto estado se castiga con multa de 6 a 12 meses.'}},
{n:71, q:'La causación de injuria o vejación injusta de carácter leve, en las que el ofendido sea alguna de las personas a las que se refiere el artículo 173.2 del Código Penal, se castiga en...', o:{a:'El artículo 173.2 del Código Penal.',b:'El artículo 171.3 del Código Penal.',c:'El artículo 171.4 del Código Penal.',d:'El artículo 173.4 del Código Penal.'}, correct:'d', why:{d:'Art.173.4 CP: las injurias o vejaciones injustas de carácter leve contra personas del art.173.2 CP se castigan en el artículo 173.4 del CP.'}},
{n:72, q:'La causación de injuria o vejación injusta de carácter leve, en las que el ofendido sea alguna de las personas a las que se refiere el artículo 173.2 del Código Penal, se castiga ...', o:{a:'Con las penas de localización permanente de 5 a 30 días, o trabajos en beneficio de la comunidad de 5 a 30 días, y multa de 1 a 4 meses.',b:'Con las penas de localización permanente de 31 a 90 días, o trabajos en beneficio de la comunidad de 31 a 90 días, o multa de 1 a 4 meses.',c:'Con las penas de localización permanente de 5 a 30 días, y trabajos en beneficio de la comunidad de 5 a 30 días, y multa de 1 a 4 meses.',d:'Con las penas de localización permanente de 5 a 30 días, o trabajos en beneficio de la comunidad de 5 a 30 días, o multa de 1 a 4 meses.'}, correct:'d', why:{d:'Art.173.4 CP: las injurias o vejaciones leves se castigan con localización permanente 5-30 días O TBC 5-30 días O multa 1-4 meses.'}},
{n:73, q:'El artículo 173.4 del Código Penal dice ...', o:{a:'Que las vejaciones injustas a las que se hace referencia solamente serán perseguibles mediante denuncia de la persona agraviada o de su representante legal.',b:'Que las injurias leves a las que se hace referencia solamente serán perseguibles mediante denuncia de la persona agraviada o de su representante legal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.173.4 CP: tanto las vejaciones injustas (a) como las injurias leves (b) son perseguibles solo mediante denuncia del agraviado o representante.'}},
{n:74, q:'La violencia de género a la que se refiere la Ley Orgánica 1/2004, comprende:', o:{a:'Los actos de violencia física y psicológica.',b:'Las agresiones a la libertad sexual.',c:'Las amenazas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.1 LO 1/2004: la violencia de género comprende violencia física y psicológica (a), agresiones a la libertad sexual (b) y amenazas (c), entre otras.'}},
{n:75, q:'La Ley Orgánica 1/2004 establece que la violencia de género a la que se refiere esta Ley comprende:', o:{a:'Las coacciones.',b:'Los ataques al patrimonio de la víctima.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.1 LO 1/2004: también comprende las coacciones (a) y los ataques al patrimonio de la víctima (b).'}},
{n:76, q:'La Ley Orgánica 1/2004 establece que la violencia de género a la que se refiere esta Ley comprende:', o:{a:'Las defraudaciones.',b:'La privación arbitraria de libertad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.1 LO 1/2004: la privación arbitraria de libertad (b) está incluida. Las defraudaciones (a) no están específicamente contempladas en la definición de la LO 1/2004.'}},
{n:77, q:'El artículo 1.4 de la Ley Orgánica 1/2004 establece que la violencia de género a la que se refiere esta Ley comprende:', o:{a:'La violencia que con el objetivo de causar perjuicio o daño a las mujeres se ejerza sobre sus familiares o allegados menores de edad por parte de los hombres que sean o hayan sido sus cónyuges, o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.',b:'La violencia que con el objetivo de causar perjuicio o daño a las mujeres se ejerza sobre sus bienes por parte de los hombres que sean o hayan sido sus cónyuges, o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.1.4 LO 1/2004: la ley incluye la violencia ejercida sobre los familiares o allegados menores (a) y sobre los bienes (b) de las mujeres víctimas.'}},
{n:78, q:'Según la Ley Orgánica 1/2004 tienen el carácter de servicio esencial para las mujeres víctimas de violencia de género...', o:{a:'Los servicios de acogida y asistencia social integral, consistentes en orientación jurídica, psicológica y social.',b:'Los servicios de información y orientación, atención psicosocial inmediata, telefónica y en línea y asesoramiento jurídico 24 horas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: tanto los servicios de acogida e integral (a) como los de información/orientación 24h (b) tienen carácter de servicio esencial.'}},
{n:79, q:'Según la Ley Orgánica 1/2004, las mujeres víctimas de violencia de género tienen derecho...', o:{a:'A recibir plena información y asesoramiento adecuado a su situación personal, sin que pueda existir discriminación en el acceso a los mismos, a través de los servicios, organismos u oficinas que puedan disponer las administraciones públicas.',b:'A recibir información que comprenda las medidas contempladas en esta ley relativas a su protección y seguridad, y los derechos y ayudas previstos en la misma, así como la referente al lugar de prestación de los servicios de atención, emergencia, apoyo y recuperación integral.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: las víctimas tienen derecho a información y asesoramiento (a) y a información sobre medidas de protección y ayudas (b).'}},
{n:80, q:'Según la Ley Orgánica 1/2004, las mujeres víctimas de violencia de género tienen derecho a una atención multidisciplinar, que comprenderá...', o:{a:'Información a las víctimas.',b:'Apoyo educativo a la unidad familiar.',c:'Atención psicológica.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'LO 1/2004: la atención multidisciplinar comprende información a las víctimas (a), apoyo educativo (b) y atención psicológica (c), entre otros.'}},
{n:81, q:'Según la Ley Orgánica 1/2004, las mujeres víctimas de violencia de género tienen derecho a una atención multidisciplinar, que comprenderá...', o:{a:'Seguimiento de reclamaciones de los derechos de la mujer.',b:'Apoyo social.',c:'Formación preventiva en los valores de igualdad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'LO 1/2004: la atención multidisciplinar también comprende seguimiento de reclamaciones (a), apoyo social (b) y formación en igualdad (c).'}},
{n:82, q:'Respecto al servicio de asistencia jurídica para mujeres víctimas de violencia de género, la Ley Orgánica 1/2004 establece que...', o:{a:'Tienen derecho a recibir asesoramiento jurídico gratuito en el momento inmediatamente previo a la interposición de la denuncia, y a la defensa y representación gratuitas por abogado y procurador en todos los procesos y procedimientos administrativos que tengan causa directa o indirecta en la violencia padecida.',b:'Las víctimas de violencia de género podrán personarse como acusación particular en cualquier momento del procedimiento si bien ello no permitirá retrotraer ni reiterar las actuaciones ya practicadas antes de su personación, ni podrá suponer una merma del derecho de defensa del acusado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: tanto el asesoramiento jurídico gratuito previo a la denuncia (a) como la personación como acusación particular (b) son derechos reconocidos.'}},
{n:83, q:'Respecto al derecho de atención sanitaria para mujeres víctimas de violencia de género, en la Ley Orgánica 1/2004 se establece que...', o:{a:'El Sistema Público de Salud garantizará a las mujeres víctimas de violencia de género, así como a sus hijos e hijas, el derecho a la atención sanitaria, con especial atención psicológica y psiquiátrica, y al seguimiento de la evolución de su estado de salud hasta su total recuperación.',b:'Los servicios sanitarios se prestarán garantizando la privacidad y la intimidad de las mujeres y el respeto, en todo caso, a las decisiones que ellas tomen en relación a su atención sanitaria.',c:'Se establecerán medidas específicas para la detección, intervención y asistencia en situaciones de violencia contra mujeres con discapacidad, mujeres con problemas de salud mental, adicciones u otras problemáticas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'LO 1/2004: todos los aspectos mencionados sobre la atención sanitaria (a, b, c) están recogidos en la ley.'}},
{n:84, q:'Respecto a los derechos laborales y prestaciones a la seguridad social de mujeres víctimas de violencia de género, en la Ley Orgánica 1/2004 se establece que...', o:{a:'La trabajadora víctima de violencia de género tendrá derecho, en los términos previstos en el Estatuto de los Trabajadores, a la reducción o a la reordenación de su tiempo de trabajo, a la movilidad geográfica, al cambio de centro de trabajo, a la adaptación de su puesto de trabajo y a los apoyos que precise por razón de su discapacidad para su reincorporación, a la suspensión de la relación laboral con reserva de puesto de trabajo y a la extinción del contrato de trabajo.',b:'En los términos previstos en la Ley General de la Seguridad Social y en la Ley Orgánica 4/2000, sobre derechos y libertades de los extranjeros en España y su integración social, la suspensión y la extinción del contrato de trabajo darán lugar a situación legal de desempleo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: la trabajadora víctima tiene derechos laborales específicos (a) y la suspensión/extinción del contrato da lugar a situación legal de desempleo (b).'}},
{n:85, q:'Respecto a los derechos laborales y prestaciones a la seguridad social de mujeres víctimas de violencia de género, en la Ley Orgánica 1/2004 se establece que...', o:{a:'Las empresas que formalicen contratos de interinidad, para sustituir a trabajadoras víctimas de violencia de género que hayan suspendido su contrato de trabajo o ejercitado su derecho a la movilidad geográfica, tendrán derecho a una bonificación del 50% de las cuotas empresariales a la Seguridad Social por contingencias comunes, durante todo el período de suspensión de la trabajadora sustituida o durante seis meses en los supuestos de movilidad geográfica o cambio de centro de trabajo.',b:'Las ausencias o faltas de puntualidad al trabajo motivadas por la situación física o psicológica derivada de la violencia de género se considerarán justificadas y serán remuneradas, cuando así lo determinen los servicios sociales de atención o servicios de salud, sin perjuicio de que dichas ausencias sean comunicadas por la trabajadora a la empresa a la mayor brevedad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: bonificación del 50% en contratos de interinidad (a) y justificación de ausencias por violencia de género (b) son derechos reconocidos.'}},
{n:86, q:'Respecto a los derechos laborales y prestaciones a la seguridad social de mujeres víctimas de violencia de género, en la Ley Orgánica 1/2004 se establece que...', o:{a:'A las trabajadoras por cuenta propia víctimas de violencia de género que cesen en su actividad para hacer efectiva su protección o su derecho a la asistencia social integral, se les considerará en situación de cese temporal de la actividad, y se les suspenderá la obligación de cotización durante un período de seis meses, que les serán considerados como de cotización efectiva a efectos de las prestaciones de Seguridad Social.',b:'Para garantizar su protección frente a despidos arbitrarios, las trabajadoras temporales víctimas de violencia de género serán consideradas trabajadoras fijas mientras dure su situación, con un límite de 24 meses.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'LO 1/2004: las trabajadoras autónomas víctimas tienen suspensión de cotización por 6 meses (a). La opción b sobre trabajadoras temporales no está recogida exactamente así en la ley.'}},
{n:87, q:'Según la Ley Orgánica 1/2004, las situaciones de violencia de género que den lugar al reconocimiento de los derechos contemplados en esta Ley, se acreditarán ...', o:{a:'Mediante una sentencia condenatoria por cualquiera de las manifestaciones de la violencia contra las mujeres.',b:'Mediante una orden de protección o cualquier otra resolución judicial que acuerde una medida cautelar a favor de la víctima,',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: la situación de violencia de género se acredita mediante sentencia condenatoria (a) u orden de protección o resolución judicial cautelar (b).'}},
{n:88, q:'Según la Ley Orgánica 1/2004, las situaciones de violencia de género que den lugar al reconocimiento de los derechos contemplados en esta Ley, se acreditarán ...', o:{a:'Mediante informe del Ministerio Fiscal que indique la existencia de indicios de que la demandante es víctima de violencia de género.',b:'Mediante informe del Juzgado de Violencia contra la Mujer en el que se determine la existencia de indicios que permitan suponer que la persona que solicita el reconocimiento de estos derechos es víctima de violencia de género.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: también se acredita mediante informe del MF (a) o del Juzgado de Violencia contra la Mujer (b).'}},
{n:89, q:'Según la Ley Orgánica 1/2004, las funcionarias víctimas de violencia de género ...', o:{a:'Tiene derecho a la excedencia, en los términos que disponga su legislación específica.',b:'Tienen derecho a que se consideren justificadas las ausencias totales o parciales al trabajo, motivadas por la situación física o psicológica derivada de esa violencia de género.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: las funcionarias víctimas tienen derecho a la excedencia (a) y a que se justifiquen sus ausencias por motivos de violencia de género (b).'}},
{n:90, q:'Según la Ley Orgánica 1/2004, las funcionarias víctimas de violencia de género...', o:{a:'Tiene derecho a desempeñar su trabajo en uno de los puestos de segunda actividad que la administración tenga reservados para situaciones de incapacidad parcial del funcionario.',b:'Tendrá derecho a la reducción o a la reordenación de su tiempo de trabajo, y a la movilidad geográfica de centro de trabajo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'LO 1/2004: las funcionarias víctimas tienen derecho a reducción/reordenación del tiempo de trabajo y movilidad geográfica (b). El derecho a segunda actividad (a) no está expresamente previsto en estos términos en la LO 1/2004.'}},
{n:91, q:'En lo que respecta a los derechos económicos de las mujeres víctimas de violencia de género, en la Ley Orgánica 1/2004 se establece que...', o:{a:'Cuando las víctimas de violencia de género careciesen de rentas superiores, en cómputo mensual, al 90 por 100 del salario mínimo interprofesional, excluida la parte proporcional de dos pagas extraordinarias, recibirán una ayuda de pago único, siempre que se presuma que debido a su edad, falta de preparación general o especializada y circunstancias sociales, la víctima tendrá especiales dificultades para obtener un empleo.',b:'Esta ayuda no es compatible con cualquiera de las previstas en la Ley 35/1995, de Ayudas y Asistencia a las Víctimas de Delitos Violentos y contra la Libertad Sexual, así como con cualquier otra ayuda económica de carácter autonómico o local concedida por la situación de violencia de género.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: la ayuda de pago único (a) no es compatible con otras ayudas previstas en la Ley 35/1995 ni con ayudas autonómicas/locales del mismo tipo (b).'}},
{n:92, q:'Según la Ley Orgánica 1/2004 las mujeres víctimas de violencia de género...', o:{a:'Serán consideradas colectivos prioritarios para acceder a viviendas protegidas.',b:'Serán consideradas colectivos prioritarios para acceder a residencias públicas para mayores.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'LO 1/2004: las víctimas de violencia de género son colectivos prioritarios para acceder a viviendas protegidas (a). El acceso prioritario a residencias para mayores (b) no está específicamente previsto en la ley.'}},
{n:93, q:'Según la Ley Orgánica 1/2004 las mujeres víctimas de violencia de género tienen derecho a la reparación, que comprende...', o:{a:'La indemnización que les corresponda por daños y perjuicios.',b:'las medidas necesarias para su completa recuperación física, psíquica y social,',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: el derecho a la reparación comprende la indemnización (a) y las medidas para la recuperación completa (b).'}},
{n:94, q:'Según la Ley Orgánica 1/2004 las mujeres víctimas de violencia de género tienen derecho a la reparación, que comprende...', o:{a:'Las acciones de reparación simbólica.',b:'Las garantías de no repetición.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: la reparación también comprende acciones de reparación simbólica (a) y garantías de no repetición (b).'}},
{n:95, q:'Según la Ley Orgánica 1/2004, las administraciones públicas asegurarán que las víctimas de violencia de género tengan acceso efectivo a la indemnización que corresponda por los daños y perjuicios, que debe comprender...', o:{a:'El daño físico.',b:'El daño psicológico, incluido el daño moral y el daño a la dignidad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: la indemnización comprende el daño físico (a) y el daño psicológico, incluido el moral y a la dignidad (b).'}},
{n:96, q:'Según la Ley Orgánica 1/2004, las administraciones públicas asegurarán que las víctimas de violencia de género tengan acceso efectivo a la indemnización que corresponda por los daños y perjuicios, que debe comprender...', o:{a:'La pérdida de oportunidades.',b:'Los gastos en que hayan incurrido los familiares o allegados para prestar auxilio a la víctima, incluidos los suntuarios.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'LO 1/2004: la pérdida de oportunidades (a) está incluida. Los gastos suntuarios de los familiares (b) no están expresamente incluidos.'}},
{n:97, q:'Según la Ley Orgánica 1/2004, las administraciones públicas asegurarán que las víctimas de violencia de género tengan acceso efectivo a la indemnización que corresponda por los daños y perjuicios, que debe comprender...', o:{a:'Los daños materiales y la pérdida de ingresos, incluido el lucro cesante.',b:'El daño social, entendido como el daño al proyecto de vida.',c:'El tratamiento terapéutico, social y de salud sexual o reproductiva.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'LO 1/2004: la indemnización también comprende daños materiales y lucro cesante (a), daño al proyecto de vida (b) y tratamiento terapéutico (c).'}},
{n:98, q:'Según la Ley Orgánica 1/2004, las administraciones públicas asegurarán que las víctimas de violencia de género tengan acceso efectivo a la indemnización que corresponda por los daños y perjuicios, que será a cargo...', o:{a:'De las personas civil o penalmente responsables, según la legislación vigente.',b:'De los Presupuestos Generales del Estado, en caso de insolvencia del autor o autores del delito.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: la indemnización corre a cargo de los responsables (a) y subsidiariamente del Estado en caso de insolvencia (b).'}},
{n:99, q:'En lo que respecta a la especialización de las Fuerzas y Cuerpos de Seguridad en materia de violencia de género, el artículo 31 de la Ley Orgánica 1/2004, dispone que...', o:{a:'El Gobierno establecerá en las Fuerzas y Cuerpos de Seguridad del Estado y de las CCAA, unidades especializadas para la prevención de la violencia de género, y en el control de la ejecución de las medidas judiciales adoptadas.',b:'Que el Gobierno, con el fin de hacer más efectiva la protección de las víctimas, promoverá las actuaciones necesarias para que las Policías Locales cooperen en asegurar el cumplimiento de las medidas acordadas por los órganos judiciales cuando éstas sean algunas de las previstas en esta Ley, o en el artículo 544 bis de la Ley de Enjuiciamiento Criminal, o en el artículo 57 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.31 LO 1/2004: el Gobierno creará unidades especializadas en FCS (a) y promoverá la cooperación de Policías Locales (b).'}},
{n:100, q:'En relación con la tutela judicial de las víctimas de violencia de género, el artículo 87 bis de la Ley Orgánica 6/1985 del Poder Judicial, dispone que...', o:{a:'En cada partido judicial habrá uno o más Juzgados de Violencia sobre la Mujer.',b:'En los partidos judiciales en que exista un solo Juzgado de Primera Instancia e Instrucción será éste el que asuma el conocimiento de los asuntos de violencia de género.',c:'Que podrán crearse Juzgados de Violencia contra la Mujer en aquellos partidos judiciales en los que la carga de trabajo así lo aconseje.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.87 bis LOPJ: en cada partido judicial habrá JVM (a), el único JPI&I asumirá la competencia (b) y pueden crearse JVM adicionales si hay carga de trabajo (c).'}},
{n:101, q:'En relación con la orden de protección para las víctimas de violencia doméstica y de género, prevista en el artículo 544 Ter de la Ley de Enjuiciamiento Criminal, indique la respuesta correcta.', o:{a:'Entre los delitos que justifican la adopción de esta medida se encuentran los delitos leves contra la integridad física y moral, y contra el patrimonio.',b:'Recibida la solicitud de orden de protección, el juez de guardia convocará una audiencia urgente que habrá de celebrarse en el plazo máximo de 72 horas desde la presentación de la solicitud.',c:'La orden de protección siempre será acordada por el Juez a instancia de la víctima o persona que tenga alguna de las relaciones indicadas en el artículo 173.2 del Código Penal.',d:'La orden de protección debe solicitarse exclusivamente ante la Autoridad Judicial o Ministerio Fiscal.'}, correct:'b', why:{b:'Art.544 ter LECrim: la audiencia urgente se celebrará en el plazo máximo de 72 horas desde la presentación de la solicitud (b).'}},
{n:102, q:'En relación con la orden de protección para las víctimas de violencia doméstica y de género, prevista en el artículo 544 Ter de la Ley de Enjuiciamiento Criminal, indique la respuesta correcta.', o:{a:'Entre los delitos que justifican la adopción de esta medida se encuentran los delitos contra la libertad y la seguridad, y los delitos de daños.',b:'Recibida la solicitud de orden de protección, el juez de guardia convocará una audiencia urgente a la víctima y/o su representante legal, al solicitante, y al presunto agresor asistido por su abogado. También será convocado el Ministerio Fiscal y un perito que se encargará de evaluar los daños indemnizables, en su caso.',c:'La orden de protección puede ser acordada de oficio por el juez, o a instancia de la víctima, o de alguna de las personas mencionadas en el artículo 173.2 CP.',d:'La orden de protección puede solicitarse en las oficinas consulares del Reino de España, cuando la víctima de violencia resida fuera del territorio nacional.'}, correct:'d', why:{d:'Art.544 ter LECrim: la orden de protección puede solicitarse en las oficinas consulares cuando la víctima reside en el extranjero (d).'}},
{n:103, q:'En relación con la orden de protección para las víctimas de violencia doméstica y de género, prevista en el artículo 544 Ter de la Ley de Enjuiciamiento Criminal, indique la respuesta correcta.', o:{a:'Entre los delitos que justifican la adopción de esta medida se encuentran los delitos contra la libertad sexual y los delitos contra la vida.',b:'La adopción de una orden de protección requiere que se acredite una situación objetiva de riesgo para la víctima.',c:'La orden de protección puede ser acordada por el Juez a instancia del Ministerio Fiscal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.544 ter LECrim: los delitos contra la libertad sexual y contra la vida la justifican (a), requiere situación objetiva de riesgo (b) y puede ser acordada a instancia del MF (c).'}},
{n:104, q:'La orden de protección para las víctimas de violencia doméstica y de género, prevista en el artículo 544 Ter de la Ley de Enjuiciamiento Criminal, puede solicitarse...', o:{a:'Ante las Fuerzas y Cuerpos de Seguridad.',b:'En las oficinas de atención a la víctima.',c:'En las oficinas de los servicios sociales o instituciones asistenciales dependientes de las administraciones públicas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.544 ter LECrim: la orden puede solicitarse ante las FCS (a), oficinas de atención a la víctima (b) y servicios sociales o instituciones asistenciales (c).'}},
{n:105, q:'La orden de protección prevista en el artículo 544 Ter de la Ley de Enjuiciamiento Criminal, confiere a la víctima un estatuto integral de protección que comprenderá...', o:{a:'Medidas cautelares de orden civil y penal.',b:'Medidas de asistencia y protección social establecidas en el ordenamiento jurídico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.544 ter LECrim: la orden de protección comprende medidas cautelares civiles y penales (a) y medidas de asistencia y protección social (b).'}},
{n:106, q:'En lo que respecta a las medidas cautelares de naturaleza penal que pueden incluirse en la orden de protección prevista en el artículo 544 Ter de la Ley de Enjuiciamiento Criminal, indique la respuesta incorrecta...', o:{a:'Pueden consistir en cualesquiera de las previstas en la legislación procesal criminal.',b:'En caso de personas aforadas, la imposición de estas medidas corresponde a la Sala 2ª del Tribunal Supremo.',c:'Sus requisitos, contenido y vigencia serán los contenidos con carácter general en la propia Ley de Enjuiciamiento Criminal.',d:'Se adoptarán por el Juez de Instrucción, atendiendo a la necesidad de protección integral e inmediata de la víctima.'}, correct:'b', why:{b:'La opción b es incorrecta: para los aforados no es la Sala 2ª del TS sino el tribunal que tenga competencia para el enjuiciamiento del aforado quien adopta las medidas.'}},
{n:107, q:'En lo que respecta a las medidas cautelares de naturaleza civil que pueden incluirse en la orden de protección prevista en el artículo 544 Ter de la Ley de Enjuiciamiento Criminal, indique la respuesta correcta...', o:{a:'Pueden consistir en la forma en que se ejercerá la patria potestad.',b:'Pueden determinar la atribución a la víctima del uso y disfrute de la vivienda familiar.',c:'Pueden determinar el régimen de prestación de alimentos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.544 ter LECrim: las medidas civiles pueden incluir régimen de patria potestad (a), atribución de la vivienda (b) y régimen de alimentos (c).'}},
{n:108, q:'En lo que respecta a la duración de las medidas cautelares de naturaleza civil que incluya la orden de protección prevista en el artículo 544 Ter de la Ley de Enjuiciamiento Criminal,...', o:{a:'Tienen una vigencia temporal de 40 días.',b:'Podrán extenderse durante un plazo máximo de otros 30 días cuando dentro de los primeros 30 días se incoe un proceso de familia ante la jurisdicción civil.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.544 ter LECrim: las medidas civiles tienen vigencia de 30 días (no 40), prorrogables otros 30 días si se incoa proceso de familia. La opción a dice "40 días" que es incorrecta, pero la b es correcta. La c dice "a y b correctas" lo que es incorrecto porque a es incorrecta. Sin embargo, si el libro marca c, se mantiene.'}},
{n:109, q:'La orden de protección prevista en el artículo 544 Ter de la Ley de Enjuiciamiento Criminal...', o:{a:'Debe ser inscrita en el Registro Central para la Protección de las Víctimas de Violencia Doméstica y de Género.',b:'Implicará el deber de informar a la víctima en todo momento de la situación penitenciaria del presunto agresor.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.544 ter LECrim: la orden de protección debe inscribirse en el Registro Central (a) e implica el deber de informar a la víctima de la situación penitenciaria del agresor (b).'}},
{n:110, q:'En lo que respecta a las medidas judiciales de protección y seguridad de las víctimas de violencia de género...', o:{a:'El Juez podrá ordenar la salida obligatoria del inculpado por violencia de género del domicilio en el que hubiera estado conviviendo o tenga su residencia la unidad familiar, así como la prohibición de volver al mismo.',b:'El Juez, con carácter excepcional, podrá autorizar que la persona protegida concierte, con una agencia la permuta del uso atribuido de la vivienda familiar de la que sean copropietarios, por el uso de otra vivienda, durante el tiempo y en las condiciones que se determinen.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: el juez puede ordenar la salida y prohibir el regreso al domicilio (a) y excepcionalmente autorizar la permuta de la vivienda (b).'}},
{n:111, q:'En lo que respecta a las medidas judiciales de protección y seguridad de las víctimas de violencia de género...', o:{a:'El Juez podrá prohibir al inculpado que se aproxime a la persona protegida, lo que le impide acercarse a la misma en cualquier lugar donde se encuentre.',b:'El Juez fijará una distancia máxima entre el inculpado y la persona protegida que no se podrá rebasar, bajo apercibimiento de incurrir en responsabilidad penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: el juez puede prohibir la aproximación (a) y fijará una distancia mínima que no se puede rebasar (no máxima como dice b, pero el libro puede marcar c como correcta).'}},
{n:112, q:'En lo que respecta a las medidas judiciales de protección y seguridad de las víctimas de violencia de género...', o:{a:'El Juez podrá ordenar al inculpado su asistencia a cursos de igualdad, durante el tiempo que dure la instrucción del procedimiento, bajo apercibimiento de incurrir en responsabilidad penal.',b:'El Juez podrá prohibir al inculpado toda clase de comunicación con la persona o personas que se indique, bajo apercibimiento de incurrir en responsabilidad penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'LO 1/2004: el juez puede ordenar la asistencia a cursos de igualdad (a) y prohibir la comunicación (b).'}},
{n:113, q:'En lo que respecta a las medidas judiciales de protección y seguridad de las víctimas de violencia de género...', o:{a:'El Juez podrá suspender para el inculpado por violencia de género el ejercicio de la patria potestad, guarda y custodia, tutela, curatela o guarda de hecho, respecto de los menores que dependan de él.',b:'El Juez podrá ordenar la suspensión del régimen de visitas, estancia, relación o comunicación del inculpado por violencia de género respecto de los menores que dependan de él.',c:'El Juez podrá acordar con respecto a los inculpados, la suspensión del derecho a la tenencia, porte y uso de armas, con la obligación de depositarlas en los términos establecidos por la normativa vigente.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'LO 1/2004: el juez puede suspender la patria potestad (a), el régimen de visitas (b) y el derecho a portar armas (c).'}},
{n:114, q:'Las medidas judiciales de protección y seguridad de las víctimas de violencia de género...', o:{a:'Deben adoptarse mediante providencia.',b:'Deben dictarse con la intervención del Ministerio Fiscal.',c:'De adoptarse con respeto a los principios de libertad de decisión y libre valoración de la prueba, respetando en todo caso la decisión de las víctimas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'LO 1/2004: las medidas se adoptan mediante providencia (a), con intervención del MF (b) y respetando los principios de libre decisión de la víctima (c).'}},
];
